local GlassBeadMaker = {}
local PRODUCTS = {
    simple_glass_beads = { name = "Preproste steklene kroglice", glassCost = 1, time = 2, cost = 25, beauty = 18, happiness = 1, description = "Preproste steklene kroglice za okras." },
    painted_trade_beads = { name = "Poslikane trgovske kroglice", glassCost = 2, paintCost = 1, time = 4, cost = 80, beauty = 32, happiness = 1, prestige = 2, description = "Poslikane trgovske kroglice za trgovce." },
    silver_cored_beads = { name = "Srebrnojedrne kroglice", glassCost = 2, silverCost = 1, paintCost = 1, time = 7, cost = 220, beauty = 48, happiness = 2, prestige = 5, description = "Srebrnojedrne kroglice za plemiče." },
    gold_foil_beads = { name = "Zlatofolijne kroglice", glassCost = 3, goldCost = 1, silverCost = 1, paintCost = 1, time = 11, cost = 540, beauty = 62, happiness = 3, prestige = 13, description = "Zlatofolijne kroglice za visoke plemiče." },
    jewel_inlaid_beads = { name = "Draguljaste kroglice", glassCost = 3, goldCost = 1, silverCost = 1, paintCost = 1, jewelCost = 1, time = 15, cost = 1200, beauty = 78, happiness = 5, prestige = 26, description = "Kroglice z draguljem za visoko plemstvo." },
    royal_grand_bead_necklace = { name = "Kraljevski veliki ogrlica kroglic", glassCost = 5, goldCost = 2, silverCost = 2, paintCost = 2, jewelCost = 2, pearlCost = 2, time = 22, cost = 2900, beauty = 92, happiness = 11, prestige = 56, description = "Velika kraljevska ogrlica kroglic z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    bead_workshop = { name = "Kroglična delavnica", cost = { gold = 220, wood = 100, stone = 100, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    bead_loft = { name = "Kroglična podstrešje", cost = { gold = 800, wood = 240, stone = 220, silver = 6, paint = 6 }, upkeep = 18, qualityBonus = 18 },
    master_bead_atelier = { name = "Mojstrski kroglični atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_bead_palace = { name = "Kraljevska kroglična palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
GlassBeadMaker.glassStock = 18; GlassBeadMaker.paintStock = 12; GlassBeadMaker.silverStock = 6; GlassBeadMaker.goldStock = 6; GlassBeadMaker.jewelStock = 4; GlassBeadMaker.pearlStock = 4
GlassBeadMaker.productStock = {}; GlassBeadMaker.buildings = {}; GlassBeadMaker.maker = nil; GlassBeadMaker.activeMaking = {}; GlassBeadMaker.totalProducts = 0; GlassBeadMaker.dayTimer = 0
function GlassBeadMaker.init() GlassBeadMaker.glassStock=18; GlassBeadMaker.paintStock=12; GlassBeadMaker.silverStock=6; GlassBeadMaker.goldStock=6; GlassBeadMaker.jewelStock=4; GlassBeadMaker.pearlStock=4; GlassBeadMaker.productStock={}; GlassBeadMaker.buildings={}; GlassBeadMaker.maker=nil; GlassBeadMaker.activeMaking={}; GlassBeadMaker.totalProducts=0; GlassBeadMaker.dayTimer=0; print("[GlassBeadMaker] Royal Glass Bead Maker System initialized (6 products, 4 buildings)") end
function GlassBeadMaker.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassBeadMaker.maker={name=n or ("Krogličar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krogličar najet: %s (spretnost: %d)",GlassBeadMaker.maker.name,s),"success") end; return true end
function GlassBeadMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassBeadMaker.build(id) local ok,e=GlassBeadMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassBeadMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassBeadMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassBeadMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassBeadMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and GlassBeadMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.paintCost and GlassBeadMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.silverCost and GlassBeadMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassBeadMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassBeadMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassBeadMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassBeadMaker.buildings==0 then return false,"Potrebna kroglična delavnica" end; if not GlassBeadMaker.maker then return false,"Potreben krogličar" end; return true end
function GlassBeadMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassBeadMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then GlassBeadMaker.glassStock=GlassBeadMaker.glassStock-d.glassCost*qty end; if d.paintCost then GlassBeadMaker.paintStock=GlassBeadMaker.paintStock-d.paintCost*qty end; if d.silverCost then GlassBeadMaker.silverStock=GlassBeadMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassBeadMaker.goldStock=GlassBeadMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassBeadMaker.jewelStock=GlassBeadMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassBeadMaker.pearlStock=GlassBeadMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassBeadMaker.maker then t=math.max(1,t-math.floor(GlassBeadMaker.maker.skill/14)) end; table.insert(GlassBeadMaker.activeMaking,{id="bead_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassBeadMaker.completeMaking(m) local q=1.0+(GlassBeadMaker.getQualityBonus()/100); if GlassBeadMaker.maker then q=q+(GlassBeadMaker.maker.skill/150) end; q=math.min(2.4,q); GlassBeadMaker.productStock[m.productType]=(GlassBeadMaker.productStock[m.productType] or 0)+m.quantity; GlassBeadMaker.totalProducts=GlassBeadMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassBeadMaker.maker then GlassBeadMaker.maker.itemsMade=GlassBeadMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassBeadMaker.maker.skill=math.min(100,GlassBeadMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kroglice izdelane: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bead.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function GlassBeadMaker.update(dt) if not _G.state then return end; GlassBeadMaker.dayTimer=GlassBeadMaker.dayTimer+dt; if GlassBeadMaker.dayTimer>=30 then GlassBeadMaker.dayTimer=0; for i=#GlassBeadMaker.activeMaking,1,-1 do local m=GlassBeadMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassBeadMaker.completeMaking(m); table.remove(GlassBeadMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassBeadMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassBeadMaker.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GlassBeadMaker.getStats() return {glassStock=GlassBeadMaker.glassStock,paintStock=GlassBeadMaker.paintStock,silverStock=GlassBeadMaker.silverStock,goldStock=GlassBeadMaker.goldStock,jewelStock=GlassBeadMaker.jewelStock,pearlStock=GlassBeadMaker.pearlStock,productStock=GlassBeadMaker.productStock,numBuildings=#GlassBeadMaker.buildings,hasMaker=GlassBeadMaker.maker~=nil,makerName=GlassBeadMaker.maker and GlassBeadMaker.maker.name or "—",makerSkill=GlassBeadMaker.maker and GlassBeadMaker.maker.skill or 0,activeMaking=#GlassBeadMaker.activeMaking,totalProducts=GlassBeadMaker.totalProducts} end
return GlassBeadMaker
